import { useState, useEffect } from "react"
import {
  collection,
  query,
  where,
  getDocs,
  Timestamp,
  orderBy,
} from "firebase/firestore"
import {
  startOfISOWeek,
  endOfISOWeek,
  addDays,
  format,
  isWithinInterval,
} from "date-fns"
import { db } from "../firebase/config"
import { ServiceTicket } from "./useServiceTickets"

export interface WeekSubtotals {
  billable: number
  nonBillable: number
  gst: number
  qst: number
  total: number
  count: number
}

export interface WeeklyData {
  weekLabel: string
  weekStart: Date
  weekEnd: Date
  tickets: ServiceTicket[]
  subtotals: WeekSubtotals
}

export interface FinancialSummary {
  totalRevenue: number
  billableRevenue: number
  nonBillableRevenue: number
  taxCollected: number
}

interface UseFinancialReportsResult {
  weeklyData: WeeklyData[]
  summary: FinancialSummary
  previousSummary: FinancialSummary
  loading: boolean
  error: string | null
}

function toTicket(d: { id: string; data: () => Record<string, unknown> }): ServiceTicket {
  const raw = d.data()
  return {
    id: d.id,
    appointmentId: raw.appointmentId as string,
    clientId: raw.clientId as string,
    clientName: raw.clientName as string,
    vehicleId: raw.vehicleId as string,
    serviceTypes: Array.isArray(raw.serviceTypes) ? raw.serviceTypes as string[] : raw.serviceType ? [raw.serviceType as string] : [],
    customServiceDescription: (raw.customServiceDescription as string) ?? "",
    quotedPrice: (raw.quotedPrice as number) ?? 0,
    estimatedDuration: (raw.estimatedDuration as number) ?? 0,
    billableAmount: (raw.billableAmount as number) ?? 0,
    taxGST: (raw.taxGST as number) ?? 0,
    taxQST: (raw.taxQST as number) ?? 0,
    nonBillableAmount: (raw.nonBillableAmount as number) ?? 0,
    sendConfirmation: (raw.sendConfirmation as boolean) ?? false,
    status: raw.status as ServiceTicket["status"],
    createdAt: (raw.createdAt as Timestamp).toDate(),
    updatedAt: (raw.updatedAt as Timestamp).toDate(),
  }
}

async function fetchTickets(start: Date, end: Date): Promise<ServiceTicket[]> {
  if (!db) return []
  const endOfDay = new Date(end)
  endOfDay.setHours(23, 59, 59, 999)

  const snap = await getDocs(
    query(
      collection(db, "serviceTickets"),
      where("createdAt", ">=", Timestamp.fromDate(start)),
      where("createdAt", "<=", Timestamp.fromDate(endOfDay)),
      orderBy("createdAt", "asc")
    )
  )
  return snap.docs.map(d => toTicket(d as Parameters<typeof toTicket>[0]))
}

function calcSubtotals(tickets: ServiceTicket[]): WeekSubtotals {
  return tickets.reduce(
    (acc, t) => ({
      billable: acc.billable + t.billableAmount,
      nonBillable: acc.nonBillable + t.nonBillableAmount,
      gst: acc.gst + t.taxGST,
      qst: acc.qst + t.taxQST,
      total: acc.total + t.billableAmount + t.taxGST + t.taxQST + t.nonBillableAmount,
      count: acc.count + 1,
    }),
    { billable: 0, nonBillable: 0, gst: 0, qst: 0, total: 0, count: 0 }
  )
}

function calcSummary(tickets: ServiceTicket[]): FinancialSummary {
  return tickets.reduce(
    (acc, t) => ({
      billableRevenue: acc.billableRevenue + t.billableAmount + t.taxGST + t.taxQST,
      nonBillableRevenue: acc.nonBillableRevenue + t.nonBillableAmount,
      taxCollected: acc.taxCollected + t.taxGST + t.taxQST,
      totalRevenue:
        acc.totalRevenue + t.billableAmount + t.taxGST + t.taxQST + t.nonBillableAmount,
    }),
    { totalRevenue: 0, billableRevenue: 0, nonBillableRevenue: 0, taxCollected: 0 }
  )
}

function groupByWeek(tickets: ServiceTicket[], start: Date, end: Date): WeeklyData[] {
  const weeks: WeeklyData[] = []
  let cursor = startOfISOWeek(start)

  while (cursor <= end) {
    const weekStart = cursor
    const weekEnd = endOfISOWeek(cursor)
    const label = `${format(weekStart, "MMM d")}–${format(weekEnd, "d")}`

    const weekTickets = tickets.filter(t =>
      isWithinInterval(t.createdAt, { start: weekStart, end: weekEnd })
    )

    weeks.push({
      weekLabel: label,
      weekStart,
      weekEnd,
      tickets: weekTickets,
      subtotals: calcSubtotals(weekTickets),
    })

    cursor = addDays(weekEnd, 1)
  }

  return weeks
}

const ZERO_SUMMARY: FinancialSummary = {
  totalRevenue: 0,
  billableRevenue: 0,
  nonBillableRevenue: 0,
  taxCollected: 0,
}

export function useFinancialReports(
  startDate: Date,
  endDate: Date
): UseFinancialReportsResult {
  const [weeklyData, setWeeklyData] = useState<WeeklyData[]>([])
  const [summary, setSummary] = useState<FinancialSummary>(ZERO_SUMMARY)
  const [previousSummary, setPreviousSummary] = useState<FinancialSummary>(ZERO_SUMMARY)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    setLoading(true)
    setError(null)

    const rangeMs = endDate.getTime() - startDate.getTime()
    const prevEnd = new Date(startDate.getTime() - 1)
    const prevStart = new Date(prevEnd.getTime() - rangeMs)

    Promise.all([
      fetchTickets(startDate, endDate),
      fetchTickets(prevStart, prevEnd),
    ])
      .then(([current, previous]) => {
        setWeeklyData(groupByWeek(current, startDate, endDate))
        setSummary(calcSummary(current))
        setPreviousSummary(calcSummary(previous))
      })
      .catch(err => setError(err.message))
      .finally(() => setLoading(false))
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [startDate.toISOString(), endDate.toISOString()])

  return { weeklyData, summary, previousSummary, loading, error }
}
