import React, { useState } from "react"
import { format } from "date-fns"
import { WeeklyData } from "../../../hooks/useFinancialReports"
import { ServiceTicket } from "../../../hooks/useServiceTickets"
import { Client } from "../../../hooks/useClients"
import { doc, getDoc } from "firebase/firestore"
import { db } from "../../../firebase/config"
import ServiceTicketDetail from "./ServiceTicketDetail"

function fmt(n: number) {
  return `$ ${n.toLocaleString("en-CA", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
}

interface WeeklyBreakdownTableProps {
  weeklyData: WeeklyData[]
  loading: boolean
}

export default function WeeklyBreakdownTable({ weeklyData, loading }: WeeklyBreakdownTableProps) {
  const [expandedWeek, setExpandedWeek] = useState<string | null>(null)
  const [selectedTicket, setSelectedTicket] = useState<ServiceTicket | null>(null)
  const [selectedClient, setSelectedClient] = useState<Client | null>(null)
  const [clientCache, setClientCache] = useState<Record<string, Client>>({})

  async function openTicket(ticket: ServiceTicket) {
    setSelectedTicket(ticket)
    if (clientCache[ticket.clientId]) {
      setSelectedClient(clientCache[ticket.clientId])
      return
    }
    if (!db) return
    const snap = await getDoc(doc(db, "clients", ticket.clientId))
    if (snap.exists()) {
      const data = snap.data()
      const client: Client = {
        id: snap.id,
        name: data.name,
        phone: data.phone,
        email: data.email ?? "",
        address: data.address ?? "",
        vehicles: data.vehicles ?? [],
        portalTokens: data.portalTokens ?? [],
        createdAt: data.createdAt.toDate(),
        updatedAt: data.updatedAt.toDate(),
      }
      setClientCache(c => ({ ...c, [client.id]: client }))
      setSelectedClient(client)
    } else {
      setSelectedClient(null)
    }
  }

  if (loading) {
    return (
      <div className="bg-white rounded-xl shadow-sm overflow-hidden">
        {[...Array(4)].map((_, i) => (
          <div key={i} className="flex gap-4 px-4 py-3 border-b border-gray-50">
            <div className="h-3 bg-gray-200 rounded animate-pulse flex-1" />
            <div className="h-3 bg-gray-200 rounded animate-pulse w-16" />
            <div className="h-3 bg-gray-200 rounded animate-pulse w-20" />
          </div>
        ))}
      </div>
    )
  }

  if (weeklyData.length === 0) {
    return (
      <div className="bg-white rounded-xl shadow-sm flex flex-col items-center justify-center py-16 text-gray-400 gap-2">
        <span className="text-4xl">💰</span>
        <p className="text-sm">No revenue data for this period. Try a different date range.</p>
      </div>
    )
  }

  // Grand totals
  const grand = weeklyData.reduce(
    (acc, w) => ({
      count: acc.count + w.subtotals.count,
      billable: acc.billable + w.subtotals.billable,
      gst: acc.gst + w.subtotals.gst,
      qst: acc.qst + w.subtotals.qst,
      nonBillable: acc.nonBillable + w.subtotals.nonBillable,
      total: acc.total + w.subtotals.total,
    }),
    { count: 0, billable: 0, gst: 0, qst: 0, nonBillable: 0, total: 0 }
  )

  return (
    <>
      <div className="bg-white rounded-xl shadow-sm overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-gray-100 text-left">
              <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide">Week</th>
              <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide text-center"># Services</th>
              <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide text-right">Billable</th>
              <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide text-right">GST</th>
              <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide text-right">QST</th>
              <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide text-right">Non-Billable</th>
              <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide text-right">Total</th>
            </tr>
          </thead>
          <tbody>
            {weeklyData.map(week => {
              const isExpanded = expandedWeek === week.weekLabel
              const isEmpty = week.subtotals.count === 0

              return (
                <React.Fragment key={week.weekLabel}>
                  {/* Week row */}
                  <tr
                    onClick={() => !isEmpty && setExpandedWeek(isExpanded ? null : week.weekLabel)}
                    className={`border-b border-gray-50 transition-colors ${
                      isEmpty
                        ? "text-gray-300"
                        : "cursor-pointer hover:bg-gray-50"
                    } ${isExpanded ? "bg-blue-50" : ""}`}
                  >
                    <td className="px-4 py-3 font-medium flex items-center gap-2">
                      {!isEmpty && (
                        <span className="text-gray-400 text-xs">{isExpanded ? "▼" : "▶"}</span>
                      )}
                      {week.weekLabel}
                    </td>
                    <td className="px-4 py-3 text-center">{week.subtotals.count || "—"}</td>
                    <td className="px-4 py-3 text-right font-mono">
                      {week.subtotals.billable > 0 ? fmt(week.subtotals.billable) : "—"}
                    </td>
                    <td className="px-4 py-3 text-right font-mono">
                      {week.subtotals.gst > 0 ? fmt(week.subtotals.gst) : "—"}
                    </td>
                    <td className="px-4 py-3 text-right font-mono">
                      {week.subtotals.qst > 0 ? fmt(week.subtotals.qst) : "—"}
                    </td>
                    <td className="px-4 py-3 text-right font-mono">
                      {week.subtotals.nonBillable > 0 ? fmt(week.subtotals.nonBillable) : "—"}
                    </td>
                    <td className="px-4 py-3 text-right font-mono font-semibold">
                      {week.subtotals.total > 0 ? fmt(week.subtotals.total) : "—"}
                    </td>
                  </tr>

                  {/* Expanded ticket rows */}
                  {isExpanded && week.tickets.map(ticket => (
                    <tr
                      key={ticket.id}
                      onClick={() => openTicket(ticket)}
                      className="bg-blue-50/50 border-b border-blue-100 cursor-pointer hover:bg-blue-100/50 transition-colors"
                    >
                      <td className="pl-10 pr-4 py-2 text-gray-600 text-xs">
                        {format(ticket.createdAt, "MMM d")}
                      </td>
                      <td className="px-4 py-2 text-xs text-gray-700 text-center" colSpan={1}>
                        {ticket.clientName}
                      </td>
                      <td className="px-4 py-2 text-xs text-gray-600 capitalize" colSpan={3}>
                        {ticket.serviceTypes.includes("custom")
                          ? ticket.customServiceDescription.slice(0, 40) || "Custom"
                          : ticket.serviceTypes.map(s => s.replace(/-/g, " ")).join(", ")}
                      </td>
                      <td className="px-4 py-2 text-xs text-gray-700 text-right font-mono" colSpan={2}>
                        {fmt(ticket.billableAmount + ticket.taxGST + ticket.taxQST + ticket.nonBillableAmount)}
                      </td>
                    </tr>
                  ))}
                </React.Fragment>
              )
            })}

            {/* Totals row */}
            <tr className="bg-gray-50 font-bold text-gray-800 border-t-2 border-gray-200">
              <td className="px-4 py-3">Total</td>
              <td className="px-4 py-3 text-center">{grand.count}</td>
              <td className="px-4 py-3 text-right font-mono">{fmt(grand.billable)}</td>
              <td className="px-4 py-3 text-right font-mono">{fmt(grand.gst)}</td>
              <td className="px-4 py-3 text-right font-mono">{fmt(grand.qst)}</td>
              <td className="px-4 py-3 text-right font-mono">{fmt(grand.nonBillable)}</td>
              <td className="px-4 py-3 text-right font-mono">{fmt(grand.total)}</td>
            </tr>
          </tbody>
        </table>
      </div>

      {selectedTicket && (
        <ServiceTicketDetail
          ticket={selectedTicket}
          client={selectedClient}
          onClose={() => { setSelectedTicket(null); setSelectedClient(null) }}
        />
      )}
    </>
  )
}
