import React, { useState } from "react"
import { graphql } from "gatsby"
import {
  subWeeks,
  subMonths,
  startOfDay,
  endOfDay,
  startOfYear,
  format,
} from "date-fns"
import { useRequireAuth } from "../../../hooks/useRequireAuth"
import { useFinancialReports } from "../../../hooks/useFinancialReports"
import AdminLayout from "../../../components/admin/AdminLayout"
import FinancialSummaryCards from "../../../components/admin/Reports/FinancialSummaryCards"
import WeeklyRevenueChart from "../../../components/admin/Reports/WeeklyRevenueChart"
import WeeklyBreakdownTable from "../../../components/admin/Reports/WeeklyBreakdownTable"

type QuickFilter = "4weeks" | "3months" | "ytd" | "custom"

function toInputDate(d: Date) {
  return format(d, "yyyy-MM-dd")
}

export default function FinancialReportsPage() {
  const { currentUser, loading: authLoading } = useRequireAuth()

  const today = new Date()
  const defaultStart = startOfDay(subWeeks(today, 4))
  const defaultEnd = endOfDay(today)

  const [fromInput, setFromInput] = useState(toInputDate(defaultStart))
  const [toInput, setToInput] = useState(toInputDate(defaultEnd))
  const [appliedStart, setAppliedStart] = useState(defaultStart)
  const [appliedEnd, setAppliedEnd] = useState(defaultEnd)
  const [activeFilter, setActiveFilter] = useState<QuickFilter>("4weeks")

  const { weeklyData, summary, previousSummary, loading, error } = useFinancialReports(
    appliedStart,
    appliedEnd
  )

  function apply() {
    setAppliedStart(startOfDay(new Date(fromInput)))
    setAppliedEnd(endOfDay(new Date(toInput)))
    setActiveFilter("custom")
  }

  function setQuick(filter: QuickFilter) {
    let s: Date, e: Date
    switch (filter) {
      case "4weeks":
        s = startOfDay(subWeeks(today, 4))
        e = endOfDay(today)
        break
      case "3months":
        s = startOfDay(subMonths(today, 3))
        e = endOfDay(today)
        break
      case "ytd":
        s = startOfYear(today)
        e = endOfDay(today)
        break
      default:
        return
    }
    setFromInput(toInputDate(s))
    setToInput(toInputDate(e))
    setAppliedStart(s)
    setAppliedEnd(e)
    setActiveFilter(filter)
  }

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (!currentUser) return null

  const quickFilters: { key: QuickFilter; label: string }[] = [
    { key: "4weeks", label: "Last 4 Weeks" },
    { key: "3months", label: "Last 3 Months" },
    { key: "ytd", label: "Year to Date" },
    { key: "custom", label: "Custom" },
  ]

  return (
    <AdminLayout currentPath="/admin/reports/financial">
      <div className="mb-6">
        <h1 className="text-xl font-bold text-gray-800">Financial Reports</h1>
        <p className="text-sm text-gray-500 mt-0.5">Weekly revenue breakdown with tax summary.</p>
      </div>

      <div className="flex flex-col gap-6">
        {/* Filters */}
        <div className="bg-white rounded-xl shadow-sm p-4">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-600 mb-1">From</label>
              <input
                type="date"
                value={fromInput}
                onChange={e => { setFromInput(e.target.value); setActiveFilter("custom") }}
                className="border border-gray-300 rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 mb-1">To</label>
              <input
                type="date"
                value={toInput}
                onChange={e => { setToInput(e.target.value); setActiveFilter("custom") }}
                className="border border-gray-300 rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <button
              onClick={apply}
              className="px-4 py-1.5 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors"
            >
              Apply
            </button>

            {/* Quick filters */}
            <div className="flex gap-2 ml-auto flex-wrap">
              {quickFilters.map(f => (
                <button
                  key={f.key}
                  onClick={() => f.key !== "custom" && setQuick(f.key)}
                  className={`px-3 py-1.5 text-xs rounded-lg border transition-colors ${
                    activeFilter === f.key
                      ? "bg-blue-600 text-white border-blue-600"
                      : "border-gray-200 text-gray-600 hover:bg-gray-100"
                  } ${f.key === "custom" ? "cursor-default" : ""}`}
                >
                  {f.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        {error && (
          <div className="bg-red-50 text-red-600 text-sm px-4 py-3 rounded-lg">{error}</div>
        )}

        {/* Summary cards */}
        <FinancialSummaryCards
          summary={summary}
          previousSummary={previousSummary}
          loading={loading}
        />

        {/* Bar chart */}
        <WeeklyRevenueChart weeklyData={weeklyData} loading={loading} />

        {/* Weekly breakdown table */}
        <WeeklyBreakdownTable weeklyData={weeklyData} loading={loading} />
      </div>
    </AdminLayout>
  )
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`
