import React from "react"
import { FinancialSummary } from "../../../hooks/useFinancialReports"

function fmt(n: number) {
  return `$ ${n.toLocaleString("en-CA", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
}

function pctChange(current: number, previous: number): number | null {
  if (previous === 0) return null
  return ((current - previous) / previous) * 100
}

interface CardProps {
  label: string
  value: number
  prevValue: number
  loading: boolean
}

function Card({ label, value, prevValue, loading }: CardProps) {
  const pct = pctChange(value, prevValue)

  if (loading) {
    return (
      <div className="bg-white rounded-xl shadow-sm p-5 flex flex-col gap-3">
        <div className="h-3 bg-gray-200 rounded animate-pulse w-24" />
        <div className="h-7 bg-gray-200 rounded animate-pulse w-36" />
        <div className="h-3 bg-gray-200 rounded animate-pulse w-16" />
      </div>
    )
  }

  return (
    <div className="bg-white rounded-xl shadow-sm p-5 flex flex-col gap-1">
      <p className="text-xs font-medium text-gray-500 uppercase tracking-wide">{label}</p>
      <p className="text-2xl font-bold text-gray-800">{fmt(value)}</p>
      {pct !== null && (
        <p className={`text-xs font-medium ${pct >= 0 ? "text-green-600" : "text-red-500"}`}>
          {pct >= 0 ? "+" : ""}{pct.toFixed(1)}% vs previous period
        </p>
      )}
      {pct === null && (
        <p className="text-xs text-gray-400">No data for previous period</p>
      )}
    </div>
  )
}

interface FinancialSummaryCardsProps {
  summary: FinancialSummary
  previousSummary: FinancialSummary
  loading: boolean
}

export default function FinancialSummaryCards({
  summary,
  previousSummary,
  loading,
}: FinancialSummaryCardsProps) {
  const cards = [
    { label: "Total Revenue", value: summary.totalRevenue, prev: previousSummary.totalRevenue },
    { label: "Billable Revenue", value: summary.billableRevenue, prev: previousSummary.billableRevenue },
    { label: "Non-Billable Revenue", value: summary.nonBillableRevenue, prev: previousSummary.nonBillableRevenue },
    { label: "Tax Collected", value: summary.taxCollected, prev: previousSummary.taxCollected },
  ]

  return (
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
      {cards.map(c => (
        <Card
          key={c.label}
          label={c.label}
          value={c.value}
          prevValue={c.prev}
          loading={loading}
        />
      ))}
    </div>
  )
}
