import React from "react"
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts"
import { WeeklyData } from "../../../hooks/useFinancialReports"

// Recharts uses browser APIs — SSR guard required for Gatsby
if (typeof window === "undefined") {
  // Module-level guard handled by early return in component below
}

function fmt(n: number) {
  return `$ ${n.toLocaleString("en-CA", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
}

interface ChartEntry {
  week: string
  Billable: number
  "Non-Billable": number
  gst: number
  qst: number
  total: number
}

interface CustomTooltipProps {
  active?: boolean
  payload?: { value: number; name: string }[]
  label?: string
}

function CustomTooltip({ active, payload, label }: CustomTooltipProps) {
  if (!active || !payload?.length) return null

  const gst = payload[0]?.payload?.gst ?? 0
  const qst = payload[0]?.payload?.qst ?? 0
  const total = payload[0]?.payload?.total ?? 0

  return (
    <div className="bg-white border border-gray-200 rounded-lg shadow-lg p-3 text-xs">
      <p className="font-semibold text-gray-700 mb-2">{label}</p>
      {payload.map(p => (
        <div key={p.name} className="flex justify-between gap-6">
          <span className="text-gray-500">{p.name}:</span>
          <span className="font-medium text-gray-800">{fmt(p.value)}</span>
        </div>
      ))}
      <div className="flex justify-between gap-6 text-gray-500">
        <span>GST:</span>
        <span>{fmt(gst)}</span>
      </div>
      <div className="flex justify-between gap-6 text-gray-500">
        <span>QST:</span>
        <span>{fmt(qst)}</span>
      </div>
      <div className="flex justify-between gap-6 border-t border-gray-100 mt-1 pt-1 font-bold text-gray-800">
        <span>Total:</span>
        <span>{fmt(total)}</span>
      </div>
    </div>
  )
}

interface WeeklyRevenueChartProps {
  weeklyData: WeeklyData[]
  loading: boolean
}

export default function WeeklyRevenueChart({ weeklyData, loading }: WeeklyRevenueChartProps) {
  // Recharts uses browser APIs — SSR guard required for Gatsby
  if (typeof window === "undefined") return null

  if (loading) {
    return (
      <div className="bg-white rounded-xl shadow-sm p-5">
        <div className="h-4 bg-gray-200 rounded animate-pulse w-40 mb-4" />
        <div className="h-56 bg-gray-100 rounded animate-pulse" />
      </div>
    )
  }

  if (weeklyData.length === 0 || weeklyData.every(w => w.subtotals.total === 0)) {
    return (
      <div className="bg-white rounded-xl shadow-sm p-5 flex flex-col items-center justify-center h-48 text-gray-400 gap-2">
        <span className="text-3xl">📊</span>
        <p className="text-sm">No revenue data for this period.</p>
      </div>
    )
  }

  const data: ChartEntry[] = weeklyData.map(w => ({
    week: w.weekLabel,
    Billable: parseFloat((w.subtotals.billable + w.subtotals.gst + w.subtotals.qst).toFixed(2)),
    "Non-Billable": parseFloat(w.subtotals.nonBillable.toFixed(2)),
    gst: w.subtotals.gst,
    qst: w.subtotals.qst,
    total: w.subtotals.total,
  }))

  return (
    <div className="bg-white rounded-xl shadow-sm p-5">
      <h3 className="text-sm font-semibold text-gray-700 mb-4">Weekly Revenue</h3>
      <ResponsiveContainer width="100%" height={240}>
        <BarChart data={data} margin={{ top: 4, right: 8, left: 8, bottom: 4 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
          <XAxis
            dataKey="week"
            tick={{ fontSize: 11, fill: "#6b7280" }}
            axisLine={false}
            tickLine={false}
          />
          <YAxis
            tickFormatter={v => `$${(v as number).toLocaleString("en-CA")}`}
            tick={{ fontSize: 11, fill: "#6b7280" }}
            axisLine={false}
            tickLine={false}
            width={72}
          />
          <Tooltip content={<CustomTooltip />} />
          <Legend wrapperStyle={{ fontSize: 12, paddingTop: 12 }} />
          <Bar dataKey="Billable" stackId="a" fill="#2563eb" radius={[0, 0, 0, 0]} />
          <Bar dataKey="Non-Billable" stackId="a" fill="#93c5fd" radius={[4, 4, 0, 0]} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  )
}
